export const VERSION = 1;
export const HOUR = 3600000;
export const RESOURCES = {wood:{name:'木材',icon:'tree-pine'},stone:{name:'石料',icon:'mountain'},food:{name:'补给',icon:'wheat'},stars:{name:'星砂',icon:'sparkles'}};
export const BUILDINGS = [
 {id:'cottage',name:'林间书屋',icon:'book-open',desc:'让每一页书，都有回响。',resource:'stars',rate:2,cost:{wood:60,stone:30,food:10},color:'#e7a34d'},
 {id:'sawmill',name:'森林工坊',icon:'axe',desc:'把森林的馈赠变成新的屋檐。',resource:'wood',rate:18,cost:{wood:50,stone:25,food:10},color:'#79a977'},
 {id:'quarry',name:'山石工坊',icon:'mountain',desc:'一块块石头，筑起稳固的村庄。',resource:'stone',rate:12,cost:{wood:65,stone:20,food:15},color:'#9cabb9'},
 {id:'farm',name:'风车农场',icon:'wheat',desc:'慢慢生长，也是一种努力。',resource:'food',rate:10,cost:{wood:75,stone:35,food:10},color:'#e4b750'},
 {id:'observatory',name:'星月天文台',icon:'telescope',desc:'为认真生活的人，收集星光。',resource:'stars',rate:5,cost:{wood:180,stone:140,food:60},color:'#9b8fd8'}
];
export const COLLECTIONS = [
 {id:'leaf',name:'琥珀叶',rarity:'common',icon:'leaf',text:'一整个秋天，藏进一片叶子。'},
 {id:'bottle',name:'海风瓶',rarity:'common',icon:'flask-conical',text:'打开时，仿佛听见很远的海。'},
 {id:'feather',name:'旅鸟羽',rarity:'common',icon:'feather',text:'一位路过村庄的朋友留下的礼物。'},
 {id:'compass',name:'旅人罗盘',rarity:'rare',icon:'compass',text:'指针总是朝向你想去的地方。'},
 {id:'moon',name:'月光怀表',rarity:'rare',icon:'watch',text:'它记得所有静静用功的夜晚。'},
 {id:'crystal',name:'极光晶簇',rarity:'epic',icon:'gem',text:'把北方的天空带回了家。'},
 {id:'whale',name:'星海鲸',rarity:'epic',icon:'waves',text:'在书页之间，游过一片银河。'},
 {id:'crown',name:'永昼之冠',rarity:'legendary',icon:'crown',text:'献给那些一次又一次重新开始的人。'}
];
export const RARITIES = {common:{name:'寻常',chance:60},rare:{name:'稀有',chance:28},epic:{name:'史诗',chance:10},legendary:{name:'传说',chance:2}};
export function initialState(now=Date.now()) {return {version:VERSION,createdAt:now,lastAccrual:now,resources:{wood:120,stone:80,food:30,stars:30},pending:{wood:0,stone:0,food:0,stars:0},buildings:{cottage:1,sawmill:1,quarry:0,farm:0,observatory:0},sessions:[],collection:{},draws:0,pity:0,timer:null};}
export function rates(s) {const r={wood:0,stone:0,food:0,stars:0};for(const b of BUILDINGS)r[b.resource]+=b.rate*s.buildings[b.id];return r;}
export function accrue(s,now=Date.now()) {const r=rates(s),hours=Math.max(0,now-s.lastAccrual)/HOUR;for(const k of Object.keys(r))s.pending[k]=Math.min(r[k]*24,s.pending[k]+hours*r[k]);s.lastAccrual=Math.max(now,s.lastAccrual);return s;}
export function collect(s,now=Date.now()){accrue(s,now);const gained={...s.pending};for(const k of Object.keys(gained)){s.resources[k]+=gained[k];s.pending[k]=0;}return gained;}
export function costFor(s,id){const b=BUILDINGS.find(b=>b.id===id);if(!b)throw Error('找不到这座建筑');return Object.fromEntries(Object.entries(b.cost).map(([k,v])=>[k,Math.ceil(v*Math.pow(1.65,s.buildings[id]))]));}
export function upgrade(s,id,now=Date.now()){if(s.buildings[id]>=5)throw Error('已经达到最高等级');const cost=costFor(s,id);if(Object.entries(cost).some(([k,v])=>s.resources[k]<v))throw Error('建材还不够，再学习一会儿或领取产出吧');accrue(s,now);for(const [k,v]of Object.entries(cost))s.resources[k]-=v;s.buildings[id]++;return s.buildings[id];}
export function studySeconds(s){return s.sessions.filter(x=>x.kind==='study').reduce((n,x)=>n+x.seconds,0);}
export function population(s){return 3+Math.floor(studySeconds(s)/3600);}
export function restCredit(s){return Math.max(0,Math.floor(studySeconds(s)/5)-s.sessions.filter(x=>x.kind==='rest').reduce((n,x)=>n+x.seconds,0));}
export function secondsBetween(s,start,end,kind='study'){return s.sessions.filter(x=>x.kind===kind).reduce((sum,x)=>sum+x.segments.reduce((v,p)=>v+Math.max(0,Math.min(end,p.end)-Math.max(start,p.start))/1000,0),0);}
export function weekStart(now=Date.now()){const d=new Date(now);d.setHours(0,0,0,0);d.setDate(d.getDate()-(d.getDay()+6)%7);return +d;}
export function timerSegments(t,now=Date.now()){if(!t)return [];let remain=t.goal*1000;const parts=[...t.segments];if(t.runningSince!==null)parts.push({start:t.runningSince,end:Math.max(t.runningSince,now)});const result=[];for(const p of parts){const length=Math.min(Math.max(0,p.end-p.start),remain);if(length>0)result.push({start:p.start,end:p.start+length});remain-=length;if(remain<=0)break;}return result;}
export function timerElapsed(t,now=Date.now()){return timerSegments(t,now).reduce((v,p)=>v+(p.end-p.start)/1000,0);}
export function startTimer(s,kind,minutes,topic,now=Date.now()){if(s.timer)throw Error('请先完成当前计时');if(!['study','rest'].includes(kind)||!Number.isInteger(minutes)||minutes<1||minutes>(kind==='rest'?15:180))throw Error('时长不在允许范围内');let goal=minutes*60;if(kind==='rest'){goal=Math.min(goal,restCredit(s));if(goal<60)throw Error('先学习 5 分钟，就能解锁 1 分钟休息奖励');}s.timer={kind,goal,topic:String(topic).trim().slice(0,80)||'自由学习',segments:[],runningSince:now};}
export function pauseTimer(s,now=Date.now()){if(!s.timer)throw Error('还没有开始计时');s.timer.segments=timerSegments(s.timer,now);s.timer.runningSince=null;}
export function resumeTimer(s,now=Date.now()){if(!s.timer)throw Error('还没有开始计时');if(timerElapsed(s.timer,now)>=s.timer.goal)throw Error('本次计时已经完成，请领取奖励');if(s.timer.runningSince===null)s.timer.runningSince=now;}
export function addSession(s,kind,segments,topic,now=Date.now(),manual=false){const seconds=segments.reduce((n,p)=>n+(p.end-p.start)/1000,0);if(seconds<60)throw Error('至少完成 1 分钟再打卡吧');if(kind==='rest'&&seconds>restCredit(s)+.001)throw Error('可奖励的休息时间不足');if(segments.some(p=>!Number.isFinite(p.start)||!Number.isFinite(p.end)||p.end>now+1000||p.start>=p.end||p.start<now-366*24*HOUR))throw Error('请填写过去一年内有效的学习时间');for(const x of s.sessions)for(const p of segments)if(x.segments.some(q=>p.start<q.end&&p.end>q.start))throw Error('这段时间已有打卡记录，请检查结束时间');const reward=kind==='study'?{wood:seconds/30,stone:seconds/60,food:0,stars:seconds/150}:{wood:0,stone:0,food:seconds/30,stars:seconds/300};for(const k of Object.keys(reward))s.resources[k]+=reward[k];s.sessions.push({id:globalThis.crypto?.randomUUID?.()||`${now}-${s.sessions.length}`,kind,topic:String(topic).trim().slice(0,80)||'自由学习',segments,seconds,endedAt:segments.at(-1).end,recordedAt:now,manual});return reward;}
export function finishTimer(s,now=Date.now()){if(!s.timer)throw Error('还没有开始计时');const t=s.timer;const reward=addSession(s,t.kind,timerSegments(t,now),t.topic,now);s.timer=null;return reward;}
export function manualStudy(s,minutes,end,topic,now=Date.now()){if(s.timer)throw Error('请先结束当前计时，再补记学习');if(!Number.isInteger(minutes)||minutes<1||minutes>240)throw Error('单次补记为 1–240 分钟');return addSession(s,'study',[{start:end-minutes*60000,end}],topic,now,true);}
export function draw(s,count=1,rng=Math.random){if(![1,5].includes(count))throw Error('请选择 1 次或 5 次寻宝');if(s.resources.stars<count*30)throw Error('星砂不足，每次寻宝需要 30 星砂');s.resources.stars-=count*30;const results=[];for(let i=0;i<count;i++){const roll=rng()*100;let rarity=roll<2?'legendary':roll<12?'epic':roll<40?'rare':'common';if(s.pity>=19&&!['epic','legendary'].includes(rarity))rarity='epic';s.pity=['epic','legendary'].includes(rarity)?0:s.pity+1;const pool=COLLECTIONS.filter(x=>x.rarity===rarity),item=pool[Math.min(pool.length-1,Math.floor(rng()*pool.length))],isNew=!s.collection[item.id];s.collection[item.id]=(s.collection[item.id]||0)+1;s.draws++;results.push({...item,isNew});}return results;}
export function validateState(x){const fail=()=>{throw Error('存档格式无效或版本不兼容，原有进度未改动');};const n=(v,max=1e12)=>typeof v==='number'&&Number.isFinite(v)&&v>=0&&v<=max;if(!x||x.version!==VERSION||!n(x.createdAt,1e14)||!n(x.lastAccrual,1e14))fail();for(const obj of ['resources','pending'])for(const k of Object.keys(RESOURCES))if(!n(x[obj]?.[k]))fail();for(const b of BUILDINGS)if(!Number.isInteger(x.buildings?.[b.id])||x.buildings[b.id]<0||x.buildings[b.id]>5)fail();if(!Array.isArray(x.sessions)||x.sessions.length>100000)fail();const intervals=[];for(const a of x.sessions){if(!['study','rest'].includes(a.kind)||typeof a.topic!=='string'||a.topic.length>80||!n(a.seconds,86400)||!n(a.endedAt,1e14)||!n(a.recordedAt,1e14)||!Array.isArray(a.segments)||!a.segments.length)fail();let sum=0;for(const p of a.segments){if(!n(p.start,1e14)||!n(p.end,1e14)||p.end<=p.start)fail();sum+=(p.end-p.start)/1000;intervals.push(p);}if(Math.abs(sum-a.seconds)>.01||a.endedAt!==a.segments.at(-1).end)fail();}intervals.sort((a,b)=>a.start-b.start);for(let i=1;i<intervals.length;i++)if(intervals[i].start<intervals[i-1].end)fail();if(!n(x.draws)||!Number.isInteger(x.draws)||!Number.isInteger(x.pity)||x.pity<0||x.pity>19||!x.collection||typeof x.collection!=='object'||Array.isArray(x.collection))fail();for(const [k,v]of Object.entries(x.collection))if(!COLLECTIONS.some(c=>c.id===k)||!Number.isInteger(v)||v<1||v>1e9)fail();if(x.timer!==null){const t=x.timer;if(!t||!['study','rest'].includes(t.kind)||typeof t.topic!=='string'||t.topic.length>80||!n(t.goal,10800)||t.goal<60||!Array.isArray(t.segments)||!(t.runningSince===null||n(t.runningSince,1e14)))fail();let prev=0;for(const p of t.segments){if(!n(p.start,1e14)||!n(p.end,1e14)||p.end<=p.start||p.start<prev)fail();prev=p.end;}if(t.runningSince!==null&&t.runningSince<prev)fail();}return JSON.parse(JSON.stringify(x));}
